//! Untagged original foreach type diagnostics and post-body invalid ranges.
//! SpacemanDMM0290db5c752fa292f9824521515b603a2afd11dc lib1430..1489,1597..1619 (GPL-3.0).
use super::*;use crate::checker_expression_visit::{IterationObserver,TypeFact};use dm_ir::{ResolveQuery as Q,ResolvedMeaning as M};use crate::check_policy::DiagnosticSeverity as Level;
pub(crate) fn fixed_level(family:&str)->Option<Level>{Some(match family{"iteration_maybe_atom"=>Level::Hint,"iteration_noniterable_type"|"iteration_procpath"|"invalid_for_range"=>Level::Error,_=>return None})}
pub(super) struct Iteration<'archive,'work,W,R:?Sized>{pub(super) inner:Arguments<'archive,'work,W,R>}
impl<W:EffectReportWork,R:Resolver+?Sized> Iteration<'_,'_,W,R>{
 fn subtype(&self,child:SymbolId,parent:SymbolId)->Result<bool,PolicyFailure>{let tree=self.inner.archive.tree();let mut current=Some(tree.lookup_type(child).ok_or("iteration actual child type absent")?);let mut remaining=tree.types().len();while let Some(id)=current{self.inner.poll()?;remaining=remaining.checked_sub(1).ok_or("iteration actual parent chain cycles")?;let node=tree.type_node(id).ok_or("iteration actual parent type absent")?;if node.path==parent{return Ok(true)}let query=Q::Parent(node.path);let expected=Resolver::resolve(tree,query);if self.inner.resolver.resolve(query)!=expected{return Err("iteration parent differs from actual current tree".into())}match expected{M::Missing=>{if tree.parent(id).is_some(){return Err("iteration missing parent contradicts immutable tree".into())}},M::Symbol(parent)=>{if tree.parent(id).and_then(|parent|tree.type_node(parent)).map(|row|row.path)!=Some(parent){return Err("iteration parent identity differs".into())}},_=>return Err("iteration parent is opaque".into())}current=tree.parent(id);}Ok(false)}

 fn emit(&mut self,family:&'static str,at:Span,message:String)->Result<(),PolicyFailure>{let severity=if fixed_level(family)==Some(Level::Hint){Severity::Warning}else{Severity::Error};push(self.inner.work,&mut self.inner.rows,Row{registration:Some((None,fixed_level(family).ok_or("iteration original site level absent")?)),diagnostic:Diagnostic{family,severity,span:at,expression_span:at,message,notes:Vec::new()},synthetic:false,reported:None})}
}
impl<W:EffectReportWork,R:Resolver+?Sized> IterationObserver<PolicyFailure> for Iteration<'_,'_,W,R>{
 fn iterable(&mut self,ty:TypeFact,at:Span)->Result<(),PolicyFailure>{self.inner.poll()?;match ty{TypeFact::Known(owner)=>{if ["/world","/list","/alist"].into_iter().any(|name|SymbolId::of(name)==owner){return Ok(())}let atom=SymbolId::of("/atom");if self.subtype(owner,atom)?{return Ok(())}let(family,message)=if self.subtype(atom,owner)?{("iteration_maybe_atom",text(self.inner.work,format_args!("iterating over a /datum which might not be an /atom"))?)}else{let path=self.inner.archive.tree().symbols().text(owner).ok_or("iteration actual type spelling absent")?;("iteration_noniterable_type",text(self.inner.work,format_args!("iterating over a {path} which cannot be iterated"))?)};self.emit(family,at,message)},TypeFact::Proc=>{let message=text(self.inner.work,format_args!("iterating over a procpath which cannot be iterated"))?;self.emit("iteration_procpath",at,message)},TypeFact::Deferred(reason)=>Err(reason.into()),TypeFact::Unknown|TypeFact::Unhinted|TypeFact::ReturnHint(..)|TypeFact::List(_)|TypeFact::NestedList{..}=>Ok(())}}
 fn invalid_range(&mut self,at:Span)->Result<(),PolicyFailure>{self.inner.poll()?;let message=text(self.inner.work,format_args!("for range loop body is never reached due to invalid range"))?;self.emit("invalid_for_range",at,message)}
}
pub fn with_archived_body<W:EffectReportWork,R:Resolver+?Sized>(archive:&BodyArchive,body:&ArchivedBody<'_>,resolver:&R,profile:PackedU128,work:&mut W,checkpoint:&dyn Fn()->io::Result<()>,consume:impl FnOnce(&Findings<'_>)->Result<(),PolicyFailure>)->Result<(),PolicyFailure>{checkpoint().map_err(PolicyFailure::Operational)?;if !body.belongs_to(archive)||resolver.source_owner()!=Some(std::ptr::from_ref(archive.tree()).cast()){return Err("iteration archive/body/resolver are foreign".into())}archive.tree().validate_checker_builtin_profile(profile).map_err(|e|format!("iteration actual profile: {e:?}"))?;let mut observer=Iteration{inner:Arguments{archive,profile,work,checkpoint,resolver,rows:Vec::new()}};let pending=(||{crate::checker_expression_visit::iteration_ranges_archived(archive,body,resolver,profile,checkpoint,&mut observer)?;let findings=Findings::from_rows(archive,std::mem::take(&mut observer.inner.rows));checkpoint().map_err(PolicyFailure::Operational)?;consume(&findings)})();if matches!(&pending,Err(PolicyFailure::Operational(_))){return pending}checkpoint().map_err(PolicyFailure::Operational)?;pending}
